import '@wangeditor/editor/dist/css/style.css' // 引入 css
import React, { useEffect, useState } from 'react'
import { Editor, Toolbar } from '@wangeditor/editor-for-react'
import styles from './index.module.less'

function MyEditor () {
  // editor 实例
  const [editor, setEditor] = useState(null) // TS 语法                // JS 语法

  // 编辑器内容
  const [html, setHtml] = useState('<p>hello</p>')

  // 工具栏配置
  const toolbarConfig = {
    toolbarKeys: [
      'bold',
      'italic',
      'underline',
      'fontSize',
      'indent',
      'lineHeight',
    ],
  }

  // 编辑器配置
  const editorConfig = {
    placeholder: '请输入内容...',
  }

  // 及时销毁 editor ，重要！
  useEffect(() => {
    return () => {
      if (editor == null) return
      editor.destroy()
      setEditor(null)
    }
  }, [editor])

  return (
    <>
      <div style={{ border: '1px solid #ccc', zIndex: 100 }}>
        <Toolbar
          editor={editor}
          defaultConfig={toolbarConfig}
          mode="default"
          style={{ borderBottom: '1px solid #ccc' }}
        />
        <Editor
          defaultConfig={editorConfig}
          value={html}
          onCreated={setEditor}
          onChange={(editor) => setHtml(editor.getHtml())}
          mode="default"
          style={{ height: '200px', overflowY: 'hidden' }}
        />
      </div>
      {/* <div style={{ marginTop: '15px' }}>{html}</div> */}
    </>
  )
}

export default MyEditor

import '@wangeditor/editor/dist/css/style.css' // 引入 css
import React, { useEffect, useState } from 'react'
import { Editor, Toolbar } from '@wangeditor/editor-for-react'
import styles from './index.module.less'

function MyEditor ({ value, onChange }) {
  // editor 实例
  const [editor, setEditor] = useState(null) // TS 语法                // JS 语法

  // 工具栏配置
  const toolbarConfig = {
    toolbarKeys: [
      'bold',
      'italic',
      'underline',
      'fontSize',
      'indent',
      'lineHeight',
    ],
  }

  // 编辑器配置
  const editorConfig = {
    placeholder: '请输入内容...',
  }

  // 及时销毁 editor ，重要！
  useEffect(() => {
    return () => {
      if (editor == null) return
      editor.destroy()
      setEditor(null)
    }
  }, [editor])

  return (
    <div className={styles['editor-wrapper']}>
      <Toolbar
        editor={editor}
        defaultConfig={toolbarConfig}
        mode="default"
        className={styles.toolbar}
      />
      <Editor
        defaultConfig={editorConfig}
        value={value}
        onCreated={setEditor}
        onChange={(editor) => {
          if (onChange) {
            onChange(editor.getHtml())
          }
        }}
        mode="default"
        style={{ height: '200px', overflowY: 'hidden' }}
        className={styles['editor-content']}
      />
    </div>
  )
}

export default MyEditor

import React, { useState } from 'react'
import Editor from '@/components/Editor'
import {
  ActionSheet,
  Button,
  Cell,
  Dialog,
  hooks,
  Input,
  Uploader,
} from 'react-vant'
import { Arrow } from '@react-vant/icons'
import useNoteClassStore from '@/store/noteClass'
import styles from './index.module.less'

export default function NotePublic () {
  const { noteClassList, addClass } = useNoteClassStore()

  const actions = [
    ...noteClassList.map(item => ({ name: item.title })),
    { name: '添加新分类', color: '#1989fa' },
  ]

  const [state, updateState] = hooks.useSetState({
    title: '',
  })

  const [noteType, setNoteType] = useState('美食')
  const [visible, setVisible] = useState(false)
  const [dialogVisible, setDialogVisible] = useState(false)
  const [newClassName, setNewClassName] = useState('')
  const [content, setContent] = useState('')

  const onSelect = (item) => {
    setVisible(false)
    if (item.name === '添加新分类') {
      setDialogVisible(true)
    } else {
      setNoteType(item.name)
    }
  }

  const onConfirm = () => {
    if (newClassName) {
      addClass({
        title: newClassName,
        id: Date.now(),
      })
      setNoteType(newClassName)
      setNewClassName('')
    }
    setDialogVisible(false)
  }

  return (
    <div className={styles['note-public']}>
      <div className={styles.editor}>
        <Editor value={content} onChange={setContent}/>
      </div>
      <div className={styles['note-wrap']}>
        <Cell>
          <Input
            prefix={'标题：'}
            value={state.title}
            onChange={title => updateState({ title })}
            placeholder="请输入标题"
            clearable
          />
        </Cell>

        <Cell>
          <Uploader
            uploadText="上传封面"
            accept="*"
            onChange={v => console.log(v)}
          />
        </Cell>

        <Cell>
          <div className={styles['type-select']}
               onClick={() => { setVisible(true) }}>
            <span>选择分类</span>
            <span className={styles['type-name']}>
              {noteType}
              <Arrow/>
            </span>
          </div>
        </Cell>

        <ActionSheet
          visible={visible}
          actions={actions}
          onSelect={onSelect}
          onClose={() => setVisible(false)}
          cancelText="取消"
          duration={250}
        />

        <Dialog
          title="添加新分类"
          visible={dialogVisible}
          showCancelButton
          onConfirm={onConfirm}
          onCancel={() => setDialogVisible(false)}
        >
          <Input
            value={newClassName}
            onChange={setNewClassName}
            placeholder="请输入新分类名称"
          />
        </Dialog>
      </div>

      <div className={styles.btn}>
        <Button type="primary" block>发布日记</Button>
      </div>
    </div>
  )
}

import React, { useState } from 'react'
import Editor from '@/components/Editor'
import {
  ActionSheet,
  Button,
  Cell,
  Dialog,
  hooks,
  Input,
  NavBar,
  Uploader,
} from 'react-vant'
import { Arrow } from '@react-vant/icons'
import useNoteClassStore from '@/store/noteClass'
import styles from './index.module.less'
import { useNavigate } from 'react-router-dom'

export default function NotePublic () {
  const { noteClassList, addClass } = useNoteClassStore()
  const navigate = useNavigate()

  const actions = [
    ...noteClassList.map(item => ({ name: item.title })),
    { name: '添加新分类', color: '#1989fa' },
  ]

  const [state, updateState] = hooks.useSetState({
    title: '',
  })

  const [noteType, setNoteType] = useState('美食')
  const [visible, setVisible] = useState(false)
  const [dialogVisible, setDialogVisible] = useState(false)
  const [newClassName, setNewClassName] = useState('')
  const [content, setContent] = useState('')

  const onSelect = (item) => {
    setVisible(false)
    if (item.name === '添加新分类') {
      setDialogVisible(true)
    } else {
      setNoteType(item.name)
    }
  }

  const onConfirm = () => {
    if (newClassName) {
      addClass({
        title: newClassName,
        id: Date.now(),
      })
      setNoteType(newClassName)
      setNewClassName('')
    }
    setDialogVisible(false)
  }

  return (
    <div className={styles['note-public']}>
      <NavBar
        title="发布笔记"
        onClickLeft={() => navigate(-1)}
      />
      <div className={styles.content}>
        <div className={styles.editor}>
          <Editor value={content} onChange={setContent}/>
        </div>
        <div className={styles['note-wrap']}>
          <Cell>
            <Input
              prefix={'标题：'}
              value={state.title}
              onChange={title => updateState({ title })}
              placeholder="请输入标题"
              clearable
            />
          </Cell>

          <Cell>
            <Uploader
              uploadText="上传封面"
              accept="*"
              onChange={v => console.log(v)}
            />
          </Cell>

          <Cell>
            <div className={styles['type-select']}
                 onClick={() => { setVisible(true) }}>
              <span>选择分类</span>
              <span className={styles['type-name']}>
              {noteType}
                <Arrow/>
            </span>
            </div>
          </Cell>

          <ActionSheet
            visible={visible}
            actions={actions}
            onSelect={onSelect}
            onClose={() => setVisible(false)}
            cancelText="取消"
            duration={250}
          />

          <Dialog
            title="添加新分类"
            visible={dialogVisible}
            showCancelButton
            onConfirm={onConfirm}
            onCancel={() => setDialogVisible(false)}
          >
            <Input
              value={newClassName}
              onChange={setNewClassName}
              placeholder="请输入新分类名称"
            />
          </Dialog>
        </div>

        <div className={styles.btn}>
          <Button type="primary" block>发布日记</Button>
        </div>
      </div>
    </div>
  )
}

