import { create } from 'zustand'

const useNoteClassStore = create((set) => ({
  noteClassList: [
    { title: '美食', id: 1 },
    { title: '旅行', id: 2 },
    { title: '恋爱', id: 3 },
    { title: '学习', id: 4 },
    { title: '吵架', id: 5 },
  ],
  addClass: (newClass) => set(state => ({
    noteClassList: [...state.noteClassList, newClass],
  })),
}))

export default useNoteClassStore
